package com.appli.nutristat;

import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import android.text.*;import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.time.*;import java.util.*;

public class MainActivity extends Activity{
 NutriDb db; LinearLayout content; Spinner profiles; NutriDb.Profile profile; int tab=0; static final int REQ_EXPORT=501,REQ_IMPORT=502;
 final int GREEN=Color.rgb(46,105,70),DARK=Color.rgb(28,68,47),BG=Color.rgb(244,248,244),ORANGE=Color.rgb(226,132,44),RED=Color.rgb(175,55,55),TEXT=Color.rgb(36,46,40),MUTED=Color.rgb(105,115,108);
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
 TextView t(String s,int z,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(dp(8),dp(7),dp(8),dp(7));if(bold)v.setTypeface(null,1);return v;} TextView title(String s){TextView v=t(s,22,true);v.setPadding(dp(4),dp(12),dp(4),dp(10));return v;}
 Button b(String s){Button v=new Button(this);v.setText(s);v.setAllCaps(false);v.setTextColor(Color.WHITE);v.setTextSize(14);v.setBackground(shape(GREEN,12));return v;} Button small(String s,int c){Button v=b(s);v.setTextSize(12);v.setBackground(shape(c,10));return v;}
 EditText e(String hint,String value){EditText x=new EditText(this);x.setHint(hint);x.setText(value);x.setSingleLine();x.setTextColor(TEXT);x.setHintTextColor(MUTED);x.setBackground(shape(Color.WHITE,10));x.setPadding(dp(12),dp(10),dp(12),dp(10));return x;}
 EditText labeled(LinearLayout p,String label,String value,String unit){p.addView(t(label+(unit.isEmpty()?"":" ("+unit+")"),13,true));EditText x=e(label,value);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.setMargins(0,0,0,dp(8));p.addView(x,lp);return x;}
 LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(12),dp(10),dp(12),dp(10));l.setBackground(shape(Color.WHITE,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));l.setLayoutParams(p);return l;} ScrollView scroll(View v){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(v);return s;} double num(EditText x,double d){try{return Double.parseDouble(x.getText().toString().replace(',','.'));}catch(Exception z){return d;}} int integer(EditText x,int d){try{return Integer.parseInt(x.getText().toString());}catch(Exception z){return d;}}
 public void onCreate(Bundle b){super.onCreate(b);immersive();db=new NutriDb(this);shell();loadProfiles(0);} public void onWindowFocusChanged(boolean h){super.onWindowFocusChanged(h);if(h)immersive();}
 void immersive(){try{getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}catch(Throwable ignored){}}
 void shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(14),dp(5),dp(8),dp(5));head.setBackgroundColor(DARK);TextView logo=t("Nutristat",26,true);logo.setTextColor(Color.WHITE);head.addView(logo,new LinearLayout.LayoutParams(0,dp(58),1));profiles=new Spinner(this);head.addView(profiles,new LinearLayout.LayoutParams(dp(165),dp(52)));root.addView(head);ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(12),dp(6),dp(12),dp(14));sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(4),dp(4),dp(4),dp(4));nav.setBackgroundColor(Color.WHITE);String[] labels={"Aujourd'hui","Calendrier","Repas","Stats","Profil"};for(int i=0;i<labels.length;i++){final int k=i;Button q=small(labels[i],k==2?ORANGE:GREEN);q.setOnClickListener(v->{tab=k;render();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(52),1);p.setMargins(dp(2),0,dp(2),0);nav.addView(q,p);}root.addView(nav);setContentView(root);profiles.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){List<NutriDb.Profile>a=db.profiles();if(i<a.size()){profile=a.get(i);render();}}});}
 void loadProfiles(long id){List<NutriDb.Profile>a=db.profiles();profiles.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));int z=0;for(int i=0;i<a.size();i++)if(a.get(i).id==id)z=i;profiles.setSelection(z);if(!a.isEmpty())profile=a.get(z);render();}
 void render(){if(profile==null)return;content.removeAllViews();if(tab==0)today();else if(tab==1)calendar();else if(tab==2)mealsTab();else if(tab==3)stats();else profileTab();}
 void progress(LinearLayout root,String name,String unit,double v,double goal,boolean max){root.addView(t(name+"   "+String.format(Locale.FRANCE,"%.1f / %.1f %s",v,goal,unit)+(max?" max":""),14,true));ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(100);p.setProgress(goal<=0?0:(int)Math.min(100,100*v/goal));root.addView(p,new LinearLayout.LayoutParams(-1,dp(14)));}
 void today(){String d=LocalDate.now().toString();NutriDb.Nutrients n=db.totals(profile.id,d);content.addView(title("Bilan du jour"));LinearLayout summary=card();TextView kcal=t(Math.round(n.cal)+" / "+Math.round(profile.cal)+" kcal",29,true);kcal.setTextColor(DARK);summary.addView(kcal);progress(summary,"Protéines","g",n.protein,profile.protein,false);progress(summary,"Glucides","g",n.carbs,profile.carbs,false);progress(summary,"Lipides","g",n.fat,profile.fat,false);progress(summary,"Fibres","g",n.fiber,profile.fiber,false);progress(summary,"Sucres","g",n.sugar,profile.sugar,true);content.addView(summary);content.addView(t("Repas enregistrés",19,true));List<NutriDb.Meal> ms=db.meals(profile.id,d);if(ms.isEmpty())content.addView(t("Aucun repas enregistré aujourd'hui.",14,false));for(NutriDb.Meal m:ms)mealCard(m);Button q=b("+ Ajouter un repas");q.setOnClickListener(v->mealStep1());content.addView(q,new LinearLayout.LayoutParams(-1,dp(50)));}
 void mealCard(NutriDb.Meal m){LinearLayout c=card();c.addView(t(m.time+"  ·  "+m.meal,15,true));c.addView(t(m.item+"  ·  "+(m.amount.isEmpty()?String.format(Locale.FRANCE,"%.1f %s",m.quantity,m.unit):m.amount)+"  ·  "+Math.round(m.cal)+" kcal",14,false));LinearLayout actions=new LinearLayout(this);Button edit=small("Modifier",GREEN),del=small("Supprimer",RED);edit.setOnClickListener(v->editMeal(m));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Supprimer cette consommation ?").setMessage(m.item+" sera retiré du bilan.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{db.deleteMeal(m.id);render();}).show());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(42),1);p.setMargins(dp(2),dp(4),dp(2),0);actions.addView(edit,p);actions.addView(del,p);c.addView(actions);content.addView(c);}
 void editMeal(NutriDb.Meal m){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(4),dp(16),dp(8));EditText date=labeled(l,"Date",m.date,"AAAA-MM-JJ"),time=labeled(l,"Heure",m.time,"HH:mm"),meal=labeled(l,"Nom du repas",m.meal,""),qty=labeled(l,"Quantité",String.valueOf(m.quantity),m.unit);new AlertDialog.Builder(this).setTitle("Modifier la consommation").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{double old=m.quantity<=0?1:m.quantity,newq=num(qty,old);NutriDb.Nutrients nn=new NutriDb.Nutrients(m.cal,m.protein,m.fat,m.carbs,m.fiber,m.sugar).scale(newq/old);db.updateMeal(m.id,profile.id,date.getText().toString(),time.getText().toString(),meal.getText().toString(),m.item,m.itemType,newq,m.unit,nn);render();}).show();}
 void calendar(){content.addView(title("Calendrier"));LinearLayout c=card();CalendarView cv=new CalendarView(this);c.addView(cv,new LinearLayout.LayoutParams(-1,dp(315)));content.addView(c);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);content.addView(box);showDay(box,LocalDate.now().toString());cv.setOnDateChangeListener((v,y,m,d)->showDay(box,String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)));}
 void showDay(LinearLayout box,String date){box.removeAllViews();NutriDb.Nutrients n=db.totals(profile.id,date);LinearLayout c=card();c.addView(t(date+" · "+Math.round(n.cal)+" kcal",16,true));c.addView(t("P "+Math.round(n.protein)+" g · G "+Math.round(n.carbs)+" g · L "+Math.round(n.fat)+" g · Fibres "+Math.round(n.fiber)+" g",13,false));for(NutriDb.Meal m:db.meals(profile.id,date))c.addView(t(m.time+" · "+m.meal+" — "+m.item+" ("+m.amount+")",13,false));box.addView(c);}

 void mealsTab(){content.addView(title("Repas et base alimentaire"));LinearLayout a=card();Button add=b("+ Ajouter un repas");add.setOnClickListener(v->mealStep1());a.addView(add,new LinearLayout.LayoutParams(-1,dp(50)));LinearLayout row=new LinearLayout(this);Button nf=small("Créer un aliment",ORANGE),nr=small("Créer une recette",DARK);nf.setOnClickListener(v->foodDialog(null));nr.setOnClickListener(v->recipeDialog(null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(44),1);p.setMargins(dp(2),dp(8),dp(2),0);row.addView(nf,p);row.addView(nr,p);a.addView(row);content.addView(a);content.addView(t("Base alimentaire",19,true));catalogBrowser(content,true);}
 String servingDetail(NutriDb.Food f){NutriDb.Nutrients n=db.forServing(f);return (f.servingLabel.isEmpty()?"1 portion type":f.servingLabel)+"\n"+Math.round(n.cal)+" kcal · Protéines "+String.format(Locale.FRANCE,"%.1f",n.protein)+" g · Glucides "+String.format(Locale.FRANCE,"%.1f",n.carbs)+" g · Lipides "+String.format(Locale.FRANCE,"%.1f",n.fat)+" g · Fibres "+String.format(Locale.FRANCE,"%.1f",n.fiber)+" g · Sucres "+String.format(Locale.FRANCE,"%.1f",n.sugar)+" g";}
 String recipeDetail(NutriDb.Recipe r){return "1 portion\n"+Math.round(r.cal)+" kcal · Protéines "+String.format(Locale.FRANCE,"%.1f",r.protein)+" g · Glucides "+String.format(Locale.FRANCE,"%.1f",r.carbs)+" g · Lipides "+String.format(Locale.FRANCE,"%.1f",r.fat)+" g · Fibres "+String.format(Locale.FRANCE,"%.1f",r.fiber)+" g · Sucres "+String.format(Locale.FRANCE,"%.1f",r.sugar)+" g";}
 void catalogBrowser(LinearLayout root,boolean editable){LinearLayout tools=card();tools.addView(t("Type",13,true));Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tous","Aliment","Recette"}));tools.addView(type);tools.addView(t("Catégorie",13,true));Spinner cats=new Spinner(this);cats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));tools.addView(cats);EditText search=e("Rechercher par nom ou catégorie…","");tools.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));root.addView(tools);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);Runnable refresh=()->{String ty=(String)type.getSelectedItem(),cat=(String)cats.getSelectedItem();List<NutriDb.CatalogItem> items=db.catalog(search.getText().toString(),cat,ty);results.removeAllViews();if(items.isEmpty())results.addView(t("Aucun résultat.",14,false));for(NutriDb.CatalogItem it:items){LinearLayout c=card();TextView name=t(it.name(),15,true);TextView detail=t(it.isRecipe()?recipeDetail(it.recipe):servingDetail(it.food),13,false);detail.setVisibility(View.GONE);name.setOnClickListener(v->detail.setVisibility(detail.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));c.addView(name);c.addView(detail);TextView catv=t(it.isRecipe()?"Recettes · "+it.recipe.categories:it.food.categories,12,false);catv.setTextColor(MUTED);c.addView(catv);if(editable){Button ed=small("Éditer",it.isRecipe()?DARK:GREEN);ed.setOnClickListener(v->{if(it.isRecipe())recipeDialog(it.recipe);else foodDialog(it.food);});c.addView(ed,new LinearLayout.LayoutParams(-1,dp(40)));}results.addView(c);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}};type.setOnItemSelectedListener(lis);cats.setOnItemSelectedListener(lis);refresh.run();}

 void foodDialog(NutriDb.Food old){NutriDb.Food f=old==null?new NutriDb.Food():old;LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(14),dp(4),dp(14),dp(12));EditText name=labeled(l,"Nom",f.name==null?"":f.name,""),cats=labeled(l,"Catégories (séparées par des virgules)",f.categories==null?"":f.categories,""),serv=labeled(l,"Quantité type / description",f.servingLabel==null?"":f.servingLabel,"");l.addView(t("Base nutritionnelle",13,true));Spinner basis=new Spinner(this);basis.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"g","ml"}));basis.setSelection("ml".equals(f.basisUnit)?1:0);l.addView(basis);l.addView(t("Unité de saisie par défaut",13,true));Spinner unit=new Spinner(this);String[] units={"g","portion","cL","càc"};unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,units));for(int i=0;i<units.length;i++)if(units[i].equals(f.defaultUnit))unit.setSelection(i);l.addView(unit);EditText base=labeled(l,"Poids/volume correspondant à 1 portion type",old==null?"100":String.valueOf(f.servingBase),"g ou ml");l.addView(t("Valeurs nutritionnelles pour 100 g ou 100 ml (utilisées pour les calculs)",12,true));EditText cal=labeled(l,"Calories",old==null?"0":String.valueOf(f.cal),"kcal"),pro=labeled(l,"Protéines",old==null?"0":String.valueOf(f.protein),"g"),carb=labeled(l,"Glucides",old==null?"0":String.valueOf(f.carbs),"g"),fat=labeled(l,"Lipides",old==null?"0":String.valueOf(f.fat),"g"),fib=labeled(l,"Fibres",old==null?"0":String.valueOf(f.fiber),"g"),sug=labeled(l,"Sucres",old==null?"0":String.valueOf(f.sugar),"g");AlertDialog dlg=new AlertDialog.Builder(this).setTitle(old==null?"Créer un aliment":"Éditer l'aliment").setView(scroll(l)).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dlg.setOnShowListener(x->{dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(name.getText().toString().trim().isEmpty()){Toast.makeText(this,"Le nom est obligatoire",Toast.LENGTH_SHORT).show();return;}f.name=name.getText().toString().trim();f.categories=cats.getText().toString().trim();f.servingLabel=serv.getText().toString().trim();f.basisUnit=(String)basis.getSelectedItem();f.defaultUnit=(String)unit.getSelectedItem();f.servingBase=num(base,100);f.cal=num(cal,0);f.protein=num(pro,0);f.carbs=num(carb,0);f.fat=num(fat,0);f.fiber=num(fib,0);f.sugar=num(sug,0);f.brand="";db.saveFood(f,true);dlg.dismiss();render();});if(old!=null){Button del=dlg.getButton(AlertDialog.BUTTON_NEGATIVE);del.setText("Supprimer");del.setTextColor(RED);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Supprimer "+f.name+" ?").setMessage("Les repas déjà enregistrés garderont leurs statistiques, mais l'aliment ne sera plus proposé.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{db.deleteFood(f.id);dlg.dismiss();render();}).show());}});dlg.show();}

 void recipeDialog(NutriDb.Recipe old){NutriDb.Recipe r=old==null?new NutriDb.Recipe():old;ArrayList<NutriDb.Ingredient> items=new ArrayList<>();if(old!=null)items.addAll(db.recipeIngredients(old.id));LinearLayout main=new LinearLayout(this);main.setOrientation(LinearLayout.VERTICAL);main.setPadding(dp(14),dp(4),dp(14),dp(12));EditText name=labeled(main,"Nom de la recette",r.name==null?"":r.name,""),cats=labeled(main,"Catégories",r.categories==null?"Plats":r.categories,""),portions=labeled(main,"Nombre total de portions de la préparation",old==null?"4":String.valueOf(r.portions),"portions");TextView sum=t("",13,false);main.addView(sum);Runnable refreshSummary=()->{StringBuilder s=new StringBuilder("Ingrédients :\n");for(NutriDb.Ingredient i:items)s.append("• ").append(i.foodName).append(" — ").append(String.format(Locale.FRANCE,"%.0f g",i.grams)).append("\n");sum.setText(items.isEmpty()?"Aucun ingrédient":s.toString());};Button addIng=small("+ Ajouter un ingrédient",ORANGE);addIng.setOnClickListener(v->ingredientPicker(items,refreshSummary));main.addView(addIng,new LinearLayout.LayoutParams(-1,dp(44)));Button clear=small("Retirer le dernier ingrédient",Color.GRAY);clear.setOnClickListener(v->{if(!items.isEmpty()){items.remove(items.size()-1);refreshSummary.run();}});main.addView(clear,new LinearLayout.LayoutParams(-1,dp(40)));refreshSummary.run();AlertDialog dlg=new AlertDialog.Builder(this).setTitle(old==null?"Créer une recette":"Éditer la recette").setView(scroll(main)).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dlg.setOnShowListener(x->{dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(name.getText().toString().trim().isEmpty()||items.isEmpty()){Toast.makeText(this,"Nom et ingrédients obligatoires",Toast.LENGTH_SHORT).show();return;}r.name=name.getText().toString().trim();r.categories=cats.getText().toString().trim();r.portions=Math.max(1,num(portions,1));db.saveRecipe(r,items);dlg.dismiss();render();});if(old!=null){Button del=dlg.getButton(AlertDialog.BUTTON_NEGATIVE);del.setText("Supprimer");del.setTextColor(RED);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Supprimer la recette ?").setMessage(r.name).setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{db.deleteRecipe(r.id);dlg.dismiss();render();}).show());}});dlg.show();}
 void ingredientPicker(ArrayList<NutriDb.Ingredient> items,Runnable done){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(12),dp(4),dp(12),dp(8));Spinner cat=new Spinner(this);cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));l.addView(t("Catégorie",13,true));l.addView(cat);EditText search=e("Rechercher un aliment…","");l.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));ScrollView sc=new ScrollView(this);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);sc.addView(results);l.addView(sc,new LinearLayout.LayoutParams(-1,dp(260)));final NutriDb.Food[] selected={null};TextView sel=t("Aucun aliment sélectionné",13,true);l.addView(sel);EditText grams=labeled(l,"Quantité de cet ingrédient","100","g");Runnable refresh=()->{results.removeAllViews();String cc=(String)cat.getSelectedItem();if("Recettes".equals(cc))cc="Toutes";for(NutriDb.Food f:db.foodsFiltered(search.getText().toString(),cc)){TextView q=t(f.name,14,false);q.setBackground(shape(BG,8));q.setOnClickListener(v->{selected[0]=f;sel.setText(f.name+" · "+f.servingLabel);});results.addView(q);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});cat.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}});refresh.run();new AlertDialog.Builder(this).setTitle("Ajouter un ingrédient").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Ajouter",(d,w)->{if(selected[0]!=null){NutriDb.Ingredient i=new NutriDb.Ingredient();i.food=selected[0];i.foodId=selected[0].id;i.foodName=selected[0].name;i.grams=num(grams,100);items.add(i);done.run();}}).show();}

 void mealStep1(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(4),dp(16),dp(10));EditText date=labeled(l,"Date",LocalDate.now().toString(),"AAAA-MM-JJ"),time=labeled(l,"Heure",LocalTime.now().withSecond(0).withNano(0).toString(),"HH:mm");l.addView(t("Nom du repas",13,true));String[] names={"Petit-déjeuner","Déjeuner","Goûter","Collation","Dîner","Autre"};Spinner meal=new Spinner(this);meal.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(meal);EditText custom=labeled(l,"Nom personnalisé","","");custom.setVisibility(View.GONE);meal.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){custom.setVisibility(i==5?View.VISIBLE:View.GONE);}});new AlertDialog.Builder(this).setTitle("Nouveau repas — informations").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Suivant",(d,w)->{String mn=(String)meal.getSelectedItem();if("Autre".equals(mn))mn=custom.getText().toString().trim().isEmpty()?"Autre":custom.getText().toString().trim();mealStep2(date.getText().toString(),time.getText().toString(),mn);}).show();}
 static class Pending {NutriDb.CatalogItem item;double qty;String unit;NutriDb.Nutrients n;}
 void mealStep2(String date,String time,String mealName){final Dialog dlg=new Dialog(this);LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout controls=card();controls.addView(t("Type",13,true));Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tous","Aliment","Recette"}));controls.addView(type);controls.addView(t("Catégorie",13,true));Spinner cats=new Spinner(this);cats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));controls.addView(cats);EditText search=e("Rechercher…","");controls.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));outer.addView(controls);ScrollView scroll=new ScrollView(this);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);scroll.addView(results);outer.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout selectedBox=card();TextView selected=t("Sélectionnez un aliment ou une recette",14,true),portion=t("",13,false);selectedBox.addView(selected);selectedBox.addView(portion);EditText qty=labeled(selectedBox,"Quantité consommée","1","");Spinner unit=new Spinner(this);selectedBox.addView(t("Unité de comptabilisation",13,true));selectedBox.addView(unit);TextView pending=t("",12,false);selectedBox.addView(pending);outer.addView(selectedBox);final NutriDb.CatalogItem[] chosen={null};ArrayList<Pending> pend=new ArrayList<>();Runnable pendText=()->pending.setText(pend.isEmpty()?"":"Déjà ajoutés : "+pend.size()+" élément(s)");Runnable setUnits=()->{if(chosen[0]==null)return;if(chosen[0].isRecipe()){unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"portion"}));qty.setText("1");portion.setText(recipeDetail(chosen[0].recipe)+"\nComptabilisation : portion");}else{NutriDb.Food f=chosen[0].food;ArrayList<String> u=new ArrayList<>();if("ml".equals(f.basisUnit)){u.add("cL");u.add("portion");}else{u.add("g");u.add("portion");if("càc".equals(f.defaultUnit))u.add("càc");}unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,u));for(int i=0;i<u.size();i++)if(u.get(i).equals(f.defaultUnit))unit.setSelection(i);qty.setText("portion".equals(f.defaultUnit)||"càc".equals(f.defaultUnit)?"1":("cL".equals(f.defaultUnit)?String.valueOf(f.servingBase/10.0):String.valueOf(f.servingBase)));portion.setText(servingDetail(f)+"\nComptabilisation : "+f.defaultUnit);}};Runnable refresh=()->{results.removeAllViews();List<NutriDb.CatalogItem> list=db.catalog(search.getText().toString(),(String)cats.getSelectedItem(),(String)type.getSelectedItem());for(NutriDb.CatalogItem it:list){LinearLayout c=card();TextView n=t(it.name(),14,true);TextView sub=t(it.isRecipe()?"Recette · 1 portion":it.food.servingLabel,12,false);c.addView(n);c.addView(sub);c.setOnClickListener(v->{chosen[0]=it;selected.setText(it.name());setUnits.run();});results.addView(c);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}};type.setOnItemSelectedListener(lis);cats.setOnItemSelectedListener(lis);LinearLayout buttons=new LinearLayout(this);buttons.setGravity(Gravity.CENTER);Button cancel=small("Annuler",Color.GRAY),add=small("+ Ajouter",ORANGE),save=small("Enregistrer",GREEN);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(52),1);bp.setMargins(dp(3),0,dp(3),0);buttons.addView(cancel,bp);LinearLayout.LayoutParams big=new LinearLayout.LayoutParams(0,dp(58),1.25f);big.setMargins(dp(3),0,dp(3),0);buttons.addView(add,big);buttons.addView(save,bp);outer.addView(buttons);cancel.setOnClickListener(v->dlg.dismiss());Runnable capture=()->{if(chosen[0]==null)return;Pending p=new Pending();p.item=chosen[0];p.qty=num(qty,1);p.unit=(String)unit.getSelectedItem();if(p.item.isRecipe())p.n=new NutriDb.Nutrients(p.item.recipe.cal,p.item.recipe.protein,p.item.recipe.fat,p.item.recipe.carbs,p.item.recipe.fiber,p.item.recipe.sugar).scale(p.qty);else p.n=db.nutrientsFor(p.item.food,p.qty,p.unit);pend.add(p);chosen[0]=null;selected.setText("Sélectionnez un autre élément");portion.setText("");search.setText("");pendText.run();};add.setOnClickListener(v->capture.run());save.setOnClickListener(v->{if(chosen[0]!=null)capture.run();if(pend.isEmpty()){Toast.makeText(this,"Ajoutez au moins un élément",Toast.LENGTH_SHORT).show();return;}for(Pending p:pend)db.addMeal(profile.id,date,time,mealName,p.item.name(),p.item.isRecipe()?"recipe":"food",p.qty,p.unit,p.n);dlg.dismiss();tab=0;render();});refresh.run();dlg.setContentView(outer);dlg.show();Window w=dlg.getWindow();if(w!=null)w.setLayout(WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.MATCH_PARENT);}

 void stats(){content.addView(title("Statistiques"));LinearLayout tabs=new LinearLayout(this);Button day=small("Journée",DARK),b7=small("7 jours",GREEN),b30=small("30 jours",GREEN);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(44),1);p.setMargins(dp(2),0,dp(2),0);tabs.addView(day,p);tabs.addView(b7,p);tabs.addView(b30,p);content.addView(tabs);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);content.addView(box);day.setOnClickListener(v->renderDayStats(box));b7.setOnClickListener(v->renderPeriodStats(box,7));b30.setOnClickListener(v->renderPeriodStats(box,30));renderDayStats(box);}
 double metric(NutriDb.Nutrients n,int k){return k==0?n.cal:k==1?n.protein:k==2?n.carbs:k==3?n.fat:k==4?n.fiber:n.sugar;} double target(int k){return k==0?profile.cal:k==1?profile.protein:k==2?profile.carbs:k==3?profile.fat:k==4?profile.fiber:profile.sugar;} String metricName(int k){return new String[]{"Calories","Protéines","Glucides","Lipides","Fibres","Sucres"}[k];} String metricUnit(int k){return k==0?"kcal":"g";}
 void renderDayStats(LinearLayout box){box.removeAllViews();List<NutriDb.HourStat>s=db.hourlyCumulative(profile.id,LocalDate.now().toString());for(int k=0;k<6;k++){box.addView(t(metricName(k)+" ("+metricUnit(k)+")",16,true));box.addView(new HourChart(this,s,k,target(k)),new LinearLayout.LayoutParams(-1,dp(180)));}box.addView(t("Tous les paramètres (% de l'objectif journalier)",16,true));box.addView(new PercentHourChart(this,s,profile),new LinearLayout.LayoutParams(-1,dp(210)));}
 void renderPeriodStats(LinearLayout box,int days){box.removeAllViews();box.addView(t("Abscisse : jours",12,false));List<NutriDb.DayStat>s=db.stats(profile.id,days);for(int k=0;k<6;k++){box.addView(t(metricName(k)+" ("+metricUnit(k)+")",16,true));box.addView(new PeriodChart(this,s,k,target(k),days),new LinearLayout.LayoutParams(-1,dp(180)));}box.addView(t("Tous les paramètres (% de l'objectif journalier)",16,true));box.addView(new PercentPeriodChart(this,s,profile,days),new LinearLayout.LayoutParams(-1,dp(210)));}
 abstract class BaseChart extends View{Paint p=new Paint(1);BaseChart(Context c){super(c);setBackgroundColor(Color.WHITE);}void dashed(boolean yes){p.setPathEffect(yes?new android.graphics.DashPathEffect(new float[]{12,8},0):null);}void txt(Canvas c,String s,float x,float y,int size){p.setColor(MUTED);p.setTextSize(size);p.setStrokeWidth(1);p.setPathEffect(null);c.drawText(s,x,y,p);}}
 class HourChart extends BaseChart{List<NutriDb.HourStat>s;int k;double goal;HourChart(Context c,List<NutriDb.HourStat>s,int k,double g){super(c);this.s=s;this.k=k;goal=g;}protected void onDraw(Canvas c){super.onDraw(c);float L=52,R=getWidth()-12,T=18,B=getHeight()-32;double max=goal;for(NutriDb.HourStat x:s)max=Math.max(max,metric(x.n,k));max=Math.max(1,max*1.12);float gy=(float)(B-goal/max*(B-T));p.setColor(MUTED);dashed(true);c.drawLine(L,gy,R,gy,p);dashed(false);txt(c,Math.round(goal)+" "+metricUnit(k),2,gy+5,18);p.setColor(GREEN);p.setStrokeWidth(4);float px=0,py=0;for(int i=0;i<s.size();i++){float x=L+(R-L)*i/24f,y=(float)(B-metric(s.get(i).n,k)/max*(B-T));if(i>0)c.drawLine(px,py,x,y,p);px=x;py=y;}txt(c,"00h",L,B+23,18);txt(c,"12h",(L+R)/2-18,B+23,18);txt(c,"24h",R-35,B+23,18);}}
 class PeriodChart extends BaseChart{List<NutriDb.DayStat>s;int k,days;double goal;PeriodChart(Context c,List<NutriDb.DayStat>s,int k,double g,int d){super(c);this.s=s;this.k=k;goal=g;days=d;}protected void onDraw(Canvas c){super.onDraw(c);float L=52,R=getWidth()-12,T=18,B=getHeight()-34;double max=goal;for(NutriDb.DayStat x:s)max=Math.max(max,metric(x.n,k));max=Math.max(1,max*1.12);float gy=(float)(B-goal/max*(B-T));p.setColor(MUTED);dashed(true);c.drawLine(L,gy,R,gy,p);dashed(false);txt(c,Math.round(goal)+" "+metricUnit(k),2,gy+5,18);p.setColor(GREEN);p.setStrokeWidth(4);float px=0,py=0;for(int i=0;i<s.size();i++){float x=L+(R-L)*i/Math.max(1,s.size()-1),y=(float)(B-metric(s.get(i).n,k)/max*(B-T));if(i>0)c.drawLine(px,py,x,y,p);px=x;py=y;}txt(c,"J1",L,B+23,18);txt(c,"J"+days,R-36,B+23,18);}}
 class PercentHourChart extends BaseChart{List<NutriDb.HourStat>s;NutriDb.Profile pr;PercentHourChart(Context c,List<NutriDb.HourStat>s,NutriDb.Profile p){super(c);this.s=s;pr=p;}protected void onDraw(Canvas c){super.onDraw(c);float L=48,R=getWidth()-10,T=18,B=getHeight()-34;double[] goals={pr.cal,pr.protein,pr.carbs,pr.fat,pr.fiber,pr.sugar};int[] colors={Color.rgb(30,110,180),GREEN,ORANGE,Color.rgb(140,80,170),Color.rgb(80,150,90),RED};float gy=B-(100f/140f)*(B-T);p.setColor(MUTED);dashed(true);c.drawLine(L,gy,R,gy,p);dashed(false);for(int k=0;k<6;k++){p.setColor(colors[k]);p.setStrokeWidth(3);float px=0,py=0;for(int i=0;i<s.size();i++){float x=L+(R-L)*i/24f;double pct=goals[k]<=0?0:100*metric(s.get(i).n,k)/goals[k];float y=(float)(B-Math.min(140,pct)/140*(B-T));if(i>0)c.drawLine(px,py,x,y,p);px=x;py=y;}}txt(c,"100%",3,gy+5,18);txt(c,"00h",L,B+23,18);txt(c,"24h",R-35,B+23,18);}}
 class PercentPeriodChart extends BaseChart{List<NutriDb.DayStat>s;NutriDb.Profile pr;int days;PercentPeriodChart(Context c,List<NutriDb.DayStat>s,NutriDb.Profile p,int d){super(c);this.s=s;pr=p;days=d;}protected void onDraw(Canvas c){super.onDraw(c);float L=48,R=getWidth()-10,T=18,B=getHeight()-34;double[] goals={pr.cal,pr.protein,pr.carbs,pr.fat,pr.fiber,pr.sugar};int[] colors={Color.rgb(30,110,180),GREEN,ORANGE,Color.rgb(140,80,170),Color.rgb(80,150,90),RED};float gy=B-(100f/140f)*(B-T);p.setColor(MUTED);dashed(true);c.drawLine(L,gy,R,gy,p);dashed(false);for(int k=0;k<6;k++){p.setColor(colors[k]);p.setStrokeWidth(3);float px=0,py=0;for(int i=0;i<s.size();i++){float x=L+(R-L)*i/Math.max(1,s.size()-1);double pct=goals[k]<=0?0:100*metric(s.get(i).n,k)/goals[k];float y=(float)(B-Math.min(140,pct)/140*(B-T));if(i>0)c.drawLine(px,py,x,y,p);px=x;py=y;}}txt(c,"100%",3,gy+5,18);txt(c,"J1",L,B+23,18);txt(c,"J"+days,R-36,B+23,18);}}

 void profileTab(){content.addView(title("Profil"));LinearLayout c=card();EditText name=labeled(c,"Nom",profile.name,""),age=labeled(c,"Âge",String.valueOf(profile.age),"ans"),targetW=labeled(c,"Poids cible",String.valueOf(profile.targetWeight),"kg"),cal=labeled(c,"Objectif calories",String.valueOf(profile.cal),"kcal/j"),pro=labeled(c,"Objectif protéines",String.valueOf(profile.protein),"g/j"),fat=labeled(c,"Objectif lipides",String.valueOf(profile.fat),"g/j"),carb=labeled(c,"Objectif glucides",String.valueOf(profile.carbs),"g/j"),fib=labeled(c,"Objectif fibres",String.valueOf(profile.fiber),"g/j"),sug=labeled(c,"Limite sucres",String.valueOf(profile.sugar),"g/j max");Button save=b("Enregistrer le profil");save.setOnClickListener(v->{long id=db.saveProfile(new NutriDb.Profile(profile.id,name.getText().toString(),integer(age,30),num(targetW,70),num(cal,2000),num(pro,120),num(fat,70),num(carb,230),num(fib,30),num(sug,50)));loadProfiles(id);Toast.makeText(this,"Profil enregistré",Toast.LENGTH_SHORT).show();});c.addView(save,new LinearLayout.LayoutParams(-1,dp(48)));content.addView(c);weightSection();backupSection();}
 void weightSection(){content.addView(t("Suivi poids",19,true));LinearLayout a=card();Button update=b("Mettre à jour mon poids");update.setOnClickListener(v->weightDialog(null));a.addView(update,new LinearLayout.LayoutParams(-1,dp(48)));content.addView(a);List<NutriDb.WeightLog> ws=db.weights(profile.id);if(ws.isEmpty())content.addView(t("Aucune mesure de poids enregistrée.",14,false));else{LinearLayout hist=card();for(int i=ws.size()-1;i>=0;i--){NutriDb.WeightLog w=ws.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(t(w.date+" · "+String.format(Locale.FRANCE,"%.1f kg",w.weight),14,false),new LinearLayout.LayoutParams(0,-2,1));Button ed=small("Modifier",GREEN);ed.setOnClickListener(v->weightDialog(w));row.addView(ed,new LinearLayout.LayoutParams(dp(92),dp(38)));hist.addView(row);}content.addView(hist);}LinearLayout tabs=new LinearLayout(this);String[] lab={"1 mois","3 mois","6 mois","1 an","Maxi"};int[] months={1,3,6,12,0};LinearLayout chartBox=new LinearLayout(this);chartBox.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<lab.length;i++){final int m=months[i];Button q=small(lab[i],i==0?DARK:GREEN);q.setOnClickListener(v->renderWeightChart(chartBox,m));tabs.addView(q,new LinearLayout.LayoutParams(0,dp(42),1));}content.addView(tabs);content.addView(chartBox);renderWeightChart(chartBox,1);}
 void weightDialog(NutriDb.WeightLog old){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(4),dp(16),dp(8));EditText date=labeled(l,"Date",old==null?LocalDate.now().toString():old.date,"AAAA-MM-JJ"),w=labeled(l,"Poids",old==null?"":String.valueOf(old.weight),"kg");AlertDialog dlg=new AlertDialog.Builder(this).setTitle(old==null?"Mettre à jour mon poids":"Modifier la mesure").setView(l).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,x)->{if(old==null)db.saveWeight(profile.id,date.getText().toString(),num(w,0));else db.updateWeight(old.id,date.getText().toString(),num(w,old.weight));render();}).create();dlg.setOnShowListener(x->{if(old!=null){Button neg=dlg.getButton(AlertDialog.BUTTON_NEGATIVE);neg.setText("Supprimer");neg.setTextColor(RED);neg.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Supprimer cette mesure ?").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,z)->{db.deleteWeight(old.id);dlg.dismiss();render();}).show());}});dlg.show();}
 void renderWeightChart(LinearLayout box,int months){box.removeAllViews();LocalDate since=months==0?null:LocalDate.now().minusMonths(months);List<NutriDb.WeightLog>w=db.weightsSince(profile.id,since);String axis=months==1?"jours":(months==3||months==6?"semaines":"mois");box.addView(t("Abscisse : "+axis+" · Ordonnée : poids (kg)",12,false));box.addView(new WeightChart(this,w,profile.targetWeight,axis),new LinearLayout.LayoutParams(-1,dp(220)));}
 class WeightChart extends BaseChart{List<NutriDb.WeightLog>w;double goal;String axis;WeightChart(Context c,List<NutriDb.WeightLog>w,double g,String a){super(c);this.w=w;goal=g;axis=a;}protected void onDraw(Canvas c){super.onDraw(c);float L=52,R=getWidth()-12,T=18,B=getHeight()-34;if(w.isEmpty()){txt(c,"Aucune donnée",L,T+30,22);return;}double min=goal,max=goal;for(NutriDb.WeightLog x:w){min=Math.min(min,x.weight);max=Math.max(max,x.weight);}double span=Math.max(2,max-min);min-=span*.15;max+=span*.15;float gy=(float)(B-(goal-min)/(max-min)*(B-T));p.setColor(MUTED);dashed(true);c.drawLine(L,gy,R,gy,p);dashed(false);txt(c,String.format(Locale.FRANCE,"%.1f kg",goal),2,gy+5,18);p.setColor(GREEN);p.setStrokeWidth(4);float px=0,py=0;for(int i=0;i<w.size();i++){float x=L+(R-L)*i/Math.max(1,w.size()-1);float y=(float)(B-(w.get(i).weight-min)/(max-min)*(B-T));if(i>0)c.drawLine(px,py,x,y,p);c.drawCircle(x,y,4,p);px=x;py=y;}txt(c,axis,L,B+23,18);}}
 void backupSection(){content.addView(t("Sauvegarde / restauration",19,true));LinearLayout c=card();c.addView(t("Le fichier Nutristat contient le profil, tous les repas et statistiques, les mesures de poids, ainsi que les aliments et recettes ajoutés ou modifiés.",13,false));Button ex=small("Exporter mon profil",GREEN),im=small("Importer un profil",ORANGE);ex.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"nutristat-"+profile.name.replaceAll("[^A-Za-z0-9_-]","_")+".json");startActivityForResult(i,REQ_EXPORT);});im.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_IMPORT);});c.addView(ex,new LinearLayout.LayoutParams(-1,dp(46)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(46));p.setMargins(0,dp(8),0,0);c.addView(im,p);content.addView(c);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(request==REQ_EXPORT){String json=db.exportProfile(profile.id).toString(2);try(OutputStream os=getContentResolver().openOutputStream(uri)){os.write(json.getBytes("UTF-8"));}Toast.makeText(this,"Profil exporté",Toast.LENGTH_LONG).show();}else if(request==REQ_IMPORT){StringBuilder sb=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(uri),"UTF-8"))){String line;while((line=r.readLine())!=null)sb.append(line).append('\n');}new AlertDialog.Builder(this).setTitle("Importer ce profil ?").setMessage("Les repas et mesures du profil actuel seront remplacés par ceux du fichier. Les aliments et recettes personnalisés seront restaurés.").setNegativeButton("Annuler",null).setPositiveButton("Importer",(d,w)->{try{db.importProfile(profile.id,new JSONObject(sb.toString()));loadProfiles(profile.id);Toast.makeText(this,"Import terminé",Toast.LENGTH_LONG).show();}catch(Exception ex){Toast.makeText(this,"Erreur d'import : "+ex.getMessage(),Toast.LENGTH_LONG).show();}}).show();}}catch(Exception ex){Toast.makeText(this,"Erreur : "+ex.getMessage(),Toast.LENGTH_LONG).show();}}
}
